using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var modelName = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY");
if (string.IsNullOrEmpty(apiKey))
{
    Console.Error.WriteLine("Error: Set the OPENAI_API_KEY environment variable.");
    return 1;
}

// --- Tool implementations ---
var researchNotes = new ResearchNotes();
var webSearchTool = new WebSearchTool();

// --- Build chat client with automatic tool invocation ---
IChatClient client = new ChatClientBuilder(
        new OpenAIClient(apiKey).GetChatClient(modelName).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(webSearchTool.SearchWeb),
    AIFunctionFactory.Create(researchNotes.AddNote),
    AIFunctionFactory.Create(researchNotes.GetNotes),
};

// --- Prompt ---
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.Error.WriteLine("No topic provided.");
    return 1;
}

Console.WriteLine($"\nResearching: {topic}\n");

var systemPrompt = """
    You are a research agent. Your job is to research the given topic thoroughly.

    Follow this workflow:
    1. Search the web for information about the topic (make 2-3 different searches
       with varied queries to get broad coverage).
    2. As you find useful information, save key findings using the note-taking tool.
    3. After gathering enough information, retrieve all your notes and produce a
       well-structured summary.

    Always cite sources when possible. Be thorough but concise.
    """;

var messages = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}"),
};

var options = new ChatOptions { Tools = tools };

// --- Agent loop ---
var response = await client.GetResponseAsync(messages, options);
Console.WriteLine("\n=== Research Summary ===\n");
Console.WriteLine(response.Text);

if (researchNotes.Count > 0)
{
    Console.WriteLine($"\n({researchNotes.Count} note(s) were recorded during research)");
}

return 0;

// --- Tool classes ---

/// <summary>Provides web search capabilities using DuckDuckGo Lite.</summary>
sealed class WebSearchTool
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
        },
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Searches the web for a query and returns a list of result titles, URLs, and snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        Console.WriteLine($"  🔍 Searching: \"{query}\"");
        try
        {
            var url = $"https://html.duckduckgo.com/html/?q={Uri.EscapeDataString(query)}";
            var html = await Http.GetStringAsync(url);
            var results = ParseResults(html);

            if (results.Count == 0)
                return "No results found.";

            return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static List<SearchResult> ParseResults(string html)
    {
        var results = new List<SearchResult>();

        // Parse DuckDuckGo Lite HTML results
        var snippetSpans = html.Split("<a class=\"result__a\"", StringSplitOptions.RemoveEmptyEntries);
        foreach (var section in snippetSpans.Skip(1).Take(5))
        {
            var title = ExtractBetween(section, ">", "</a>")?.Trim();
            var href = ExtractBetween(section, "href=\"", "\"");
            var snippet = ExtractBetween(section, "<a class=\"result__snippet\"", "</a>");
            snippet = snippet is not null ? ExtractAfter(snippet, ">") : null;

            if (title is null || href is null) continue;

            // Clean HTML tags from title and snippet
            title = StripHtml(title);
            snippet = snippet is not null ? StripHtml(snippet) : "";

            results.Add(new SearchResult(title, href, snippet));
        }

        return results;
    }

    private static string? ExtractBetween(string text, string start, string end)
    {
        var startIdx = text.IndexOf(start, StringComparison.Ordinal);
        if (startIdx < 0) return null;
        startIdx += start.Length;
        var endIdx = text.IndexOf(end, startIdx, StringComparison.Ordinal);
        return endIdx < 0 ? null : text[startIdx..endIdx];
    }

    private static string? ExtractAfter(string text, string marker)
    {
        var idx = text.IndexOf(marker, StringComparison.Ordinal);
        return idx < 0 ? null : text[(idx + marker.Length)..];
    }

    private static string StripHtml(string html) =>
        System.Text.RegularExpressions.Regex.Replace(html, "<[^>]+>", "").Trim();

    record SearchResult(string Title, string Url, string Snippet);
}

/// <summary>Note-taking tool for the research agent to record findings.</summary>
sealed class ResearchNotes
{
    private readonly List<Note> _notes = [];

    public int Count => _notes.Count;

    [Description("Saves a research note with a source URL. Use this to record key findings.")]
    public string AddNote(
        [Description("The content of the note")] string content,
        [Description("The source URL for the information")] string source)
    {
        _notes.Add(new Note(content, source, DateTime.UtcNow));
        Console.WriteLine($"  📝 Note saved ({_notes.Count} total)");
        return $"Note saved successfully. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieves all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return JsonSerializer.Serialize(_notes, new JsonSerializerOptions { WriteIndented = true });
    }

    record Note(string Content, string Source, DateTime SavedAt);
}

